llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "LCB01-0371 had an absolute oral bioavailability of 99.75% after a single 800 mg oral dose in healthy male volunteers, using an IV 400 mg reference dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Lamivudine had an absolute oral bioavailability of 95 ± 5% in fasted patients with asymptomatic HIV infection after oral capsule administration compared with IV dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Maribavir had a numeric oral bioavailability of 30–40% in healthy volunteers and HIV-infected patients, which is the lowest numeric value among the evidence but still exceeds the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred evidence molecules support high oral bioavailability; direct absolute F measurements in humans range from 30–40% to 99.75%, with most values in the 70–100% range. No affirmative low-bioavailability evidence was retrieved.",
  "evidence_gaps": [
    "Several records are qualitative ('good', 'excellent', 'high') without numeric F values, providing supportive but less quantitative evidence.",
    "One record for mericitabine reports excellent oral bioavailability but rapid conversion to an active metabolite, leaving some uncertainty about whether F refers to the parent or active species.",
    "No retrieved record reports oral bioavailability below 20%, so there is no direct contradictory evidence to weigh."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

